-- Ascend · starter bank: 90 original SAT-style questions (published). Run after 0002_ascend.sql.
insert into public.ascend_questions (id, subject, level, domain, skill, passage, data_table, question, choices, answer_index, accept, explanation, status, source, published_at) values
('m1', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 3x + 7 = 22, what is the value of x?', '["3","5","7","15"]'::jsonb, 1, null, 'Subtract 7 from both sides: 3x = 15. Divide by 3: x = 5.', 'published', 'bank', now()),
('m2', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A phone plan costs $25 per month plus $0.10 for each text message sent. Which expression gives the monthly cost, in dollars, for a month in which t texts are sent?', '["25t + 0.10","0.10t + 25","25.10t","25 + 10t"]'::jsonb, 1, null, 'The fixed charge is 25 and each of the t texts adds 0.10, so the cost is 0.10t + 25.', 'published', 'bank', now()),
('m3', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'The ratio of cats to dogs at an animal shelter is 3 : 5. If there are 40 dogs at the shelter, how many cats are there?', '["15","24","25","64"]'::jsonb, 1, null, '3/5 = c/40, so c = 40 × 3 ÷ 5 = 24.', 'published', 'bank', now()),
('m4', 'math', 1, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'What is 20% of 35?', null, null, '["7"]'::jsonb, '0.20 × 35 = 7.', 'published', 'bank', now()),
('m5', 'math', 1, 'Geometry and Trigonometry', 'Right triangles', null, null, 'A rectangle has a length of 12 inches and a width of 5 inches. What is the length, in inches, of a diagonal of the rectangle?', '["13","15","17","60"]'::jsonb, 0, null, 'The diagonal is the hypotenuse of a right triangle with legs 12 and 5: √(144 + 25) = √169 = 13.', 'published', 'bank', now()),
('m6', 'math', 1, 'Algebra', 'Linear functions', null, null, 'The function f is defined by f(x) = 2x − 9. What is the value of f(6)?', '["−3","3","12","21"]'::jsonb, 1, null, 'f(6) = 2(6) − 9 = 12 − 9 = 3.', 'published', 'bank', now()),
('m7', 'math', 1, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'A student’s five test scores are 82, 90, 75, 88, and 90. What is the median of these scores?', '["75","85","88","90"]'::jsonb, 2, null, 'In order: 75, 82, 88, 90, 90. The middle value is 88.', 'published', 'bank', now()),
('m8', 'math', 1, 'Algebra', 'Systems of linear equations', null, null, 'x + y = 10
x − y = 4
What is the value of x in the solution to the system of equations above?', '["3","6","7","14"]'::jsonb, 2, null, 'Add the equations: 2x = 14, so x = 7.', 'published', 'bank', now()),
('m9', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x^{2})(x^{3})?', '["x^{5}","x^{6}","2x^{5}","x^{9}"]'::jsonb, 0, null, 'When multiplying powers with the same base, add the exponents: 2 + 3 = 5.', 'published', 'bank', now()),
('m10', 'math', 1, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A circle has a radius of 4 centimeters. What is the area of the circle, in square centimeters?', '["4π","8π","16π","64π"]'::jsonb, 2, null, 'Area = πr² = π(4²) = 16π.', 'published', 'bank', now()),
('m11', 'math', 1, 'Problem-Solving and Data Analysis', 'Ratios, rates, and proportions', null, null, 'A car travels 150 miles in 2.5 hours at a constant speed. What is the car’s speed, in miles per hour?', null, null, '["60"]'::jsonb, 'Speed = distance ÷ time = 150 ÷ 2.5 = 60.', 'published', 'bank', now()),
('m12', 'math', 1, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to 3(2x − 5) − x?', '["5x − 15","5x − 5","6x − 15","7x − 15"]'::jsonb, 0, null, 'Distribute: 6x − 15 − x = 5x − 15.', 'published', 'bank', now()),
('m13', 'math', 1, 'Algebra', 'Linear functions', null, null, 'A line in the xy-plane passes through the points (0, 2) and (3, 8). What is the slope of the line?', '["1/2","2","3","6"]'::jsonb, 1, null, 'Slope = (8 − 2) ÷ (3 − 0) = 6 ÷ 3 = 2.', 'published', 'bank', now()),
('m14', 'math', 1, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'Two angles are supplementary. One of the angles measures 115°. What is the measure of the other angle?', '["25°","65°","75°","245°"]'::jsonb, 1, null, 'Supplementary angles add to 180°: 180 − 115 = 65.', 'published', 'bank', now()),
('m15', 'math', 1, 'Algebra', 'Linear equations in one variable', null, null, 'If 2(n + 3) = 18, what is the value of n?', null, null, '["6"]'::jsonb, 'Divide by 2: n + 3 = 9, so n = 6.', 'published', 'bank', now()),
('n1', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Which of the following points lies on the line y = −2x + 5?', '["(1, 3)","(2, 3)","(3, 1)","(0, −5)"]'::jsonb, 0, null, 'Substitute x = 1: y = −2 + 5 = 3, so (1, 3) is on the line. Each other point fails the equation.', 'published', 'bank', now()),
('n2', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the positive solution to x^{2} − 9 = 0?', null, null, '["3"]'::jsonb, 'x² = 9, so x = 3 or x = −3. The positive solution is 3.', 'published', 'bank', now()),
('n3', 'math', 2, 'Problem-Solving and Data Analysis', 'Percentages', null, null, 'A shirt originally priced at $40 is on sale for 15% off. An 8% sales tax is then applied to the sale price. What is the final price of the shirt?', '["$34.00","$36.72","$36.80","$37.20"]'::jsonb, 1, null, 'Sale price: 40 × 0.85 = 34. With tax: 34 × 1.08 = 36.72.', 'published', 'bank', now()),
('n4', 'math', 2, 'Algebra', 'Systems of linear equations', null, null, '2x + 3y = 12
x − y = 1
What is the value of y in the solution to the system above?', '["1","2","3","4"]'::jsonb, 1, null, 'From the second equation, x = y + 1. Substitute: 2(y + 1) + 3y = 12, so 5y = 10 and y = 2.', 'published', 'bank', now()),
('n5', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'The function f is defined by f(x) = x^{2} − 4x + 1. What is the value of f(−2)?', '["−11","−3","5","13"]'::jsonb, 3, null, 'f(−2) = (−2)² − 4(−2) + 1 = 4 + 8 + 1 = 13.', 'published', 'bank', now()),
('n6', 'math', 2, 'Geometry and Trigonometry', 'Lines, angles, and triangles', null, null, 'The measures of the angles of a triangle are in the ratio 2 : 3 : 4. What is the measure of the largest angle?', '["40°","60°","80°","90°"]'::jsonb, 2, null, '2k + 3k + 4k = 180, so k = 20. The largest angle is 4 × 20 = 80°.', 'published', 'bank', now()),
('n7', 'math', 2, 'Advanced Math', 'Nonlinear functions', null, null, 'A colony of 500 bacteria doubles in size every 3 hours. Which function gives the number of bacteria after t hours?', '["P(t) = 500(2)^{t/3}","P(t) = 500(2)^{3t}","P(t) = 500(3)^{t/2}","P(t) = 1,000t/3"]'::jsonb, 0, null, 'The population is multiplied by 2 once for every 3 hours, so the exponent is t/3.', 'published', 'bank', now()),
('n8', 'math', 2, 'Problem-Solving and Data Analysis', 'One-variable data', null, null, 'The mean of four numbers is 15. Three of the numbers are 10, 12, and 20. What is the fourth number?', null, null, '["18"]'::jsonb, 'The four numbers total 4 × 15 = 60. 60 − (10 + 12 + 20) = 18.', 'published', 'bank', now()),
('n9', 'math', 2, 'Algebra', 'Linear inequalities', null, null, 'Which of the following is the solution to 5 − 2x > 11?', '["x > −3","x < −3","x > 3","x < 3"]'::jsonb, 1, null, 'Subtract 5: −2x > 6. Dividing by −2 flips the inequality: x < −3.', 'published', 'bank', now()),
('n10', 'math', 2, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'A right triangle has legs of length 9 and 12. What is the sine of the angle opposite the side of length 9?', '["3/5","4/5","3/4","4/3"]'::jsonb, 0, null, 'The hypotenuse is √(81 + 144) = 15. sine = opposite ÷ hypotenuse = 9/15 = 3/5.', 'published', 'bank', now()),
('n11', 'math', 2, 'Advanced Math', 'Equivalent expressions', null, null, 'Which expression is equivalent to (x + 3)(x − 5)?', '["x^{2} − 2x − 15","x^{2} + 2x − 15","x^{2} − 15","x^{2} − 8x − 15"]'::jsonb, 0, null, 'x² − 5x + 3x − 15 = x² − 2x − 15.', 'published', 'bank', now()),
('n12', 'math', 2, 'Problem-Solving and Data Analysis', 'Inference from sample statistics', null, null, 'A random sample of 200 students at a school of 1,500 students found that 46 of them prefer soccer to all other sports. Based on the sample, what is the best estimate of the number of students at the school who prefer soccer?', null, null, '["345"]'::jsonb, '46 ÷ 200 = 0.23. 0.23 × 1,500 = 345.', 'published', 'bank', now()),
('n13', 'math', 2, 'Algebra', 'Linear functions', null, null, 'Which equation represents the line that is parallel to y = 3x − 4 and passes through the point (2, 1)?', '["y = 3x − 5","y = −(1/3)x + 5/3","y = 3x + 1","y = 3x − 7"]'::jsonb, 0, null, 'A parallel line has slope 3. Use (2, 1): 1 = 3(2) + b, so b = −5.', 'published', 'bank', now()),
('n14', 'math', 2, 'Geometry and Trigonometry', 'Area and volume', null, null, 'A right circular cylinder has a radius of 3 and a height of 10. What is the volume of the cylinder?', '["30π","60π","90π","900π"]'::jsonb, 2, null, 'V = πr²h = π(9)(10) = 90π.', 'published', 'bank', now()),
('n15', 'math', 2, 'Advanced Math', 'Nonlinear equations', null, null, 'If 4^{x} = 64, what is the value of x?', null, null, '["3"]'::jsonb, '4³ = 64, so x = 3.', 'published', 'bank', now()),
('h1', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'In the equation x^{2} − 6x + c = 0, c is a constant. If the equation has exactly one real solution, what is the value of c?', null, null, '["9"]'::jsonb, 'Exactly one real solution means the discriminant is 0: (−6)² − 4(1)(c) = 36 − 4c = 0, so c = 9.', 'published', 'bank', now()),
('h2', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The graph of y = 2(x − 3)^{2} − 8 crosses the x-axis at two points. What is the sum of the x-coordinates of these two points?', '["−6","3","4","6"]'::jsonb, 3, null, 'Set y = 0: (x − 3)² = 4, so x = 1 or x = 5. The sum is 6. (Both points sit symmetrically around the vertex x = 3.)', 'published', 'bank', now()),
('h3', 'math', 3, 'Algebra', 'Systems of linear equations', null, null, '3x + ky = 7
6x + 10y = 5
In the system above, k is a constant. For what value of k does the system have no solution?', '["−5","3","5","10"]'::jsonb, 2, null, 'No solution means the lines are parallel but not the same. The x-coefficients have ratio 3/6 = 1/2, so k/10 = 1/2 and k = 5. The constants 7 and 5 are not in that ratio, so the lines are distinct.', 'published', 'bank', now()),
('h4', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle in the xy-plane has the equation x^{2} + y^{2} − 6x + 8y = 0. What is the radius of the circle?', '["√7","5","10","25"]'::jsonb, 1, null, 'Complete the square: (x − 3)² + (y + 4)² = 9 + 16 = 25. The radius is √25 = 5.', 'published', 'bank', now()),
('h5', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'The function f is defined by f(x) = (x + 2)/(x − 1). For what value of x is f(x) = 3?', null, null, '["2.5","5/2"]'::jsonb, 'x + 2 = 3(x − 1) = 3x − 3, so 5 = 2x and x = 5/2.', 'published', 'bank', now()),
('h6', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'A car bought for $24,000 loses 12% of its value each year. Which expression gives the car’s value, in dollars, after 4 years?', '["24,000(0.88)^{4}","24,000(0.12)^{4}","24,000 − 4(0.12)(24,000)","24,000(1.12)^{4}"]'::jsonb, 0, null, 'Each year the car keeps 88% of its value, so multiply by 0.88 four times.', 'published', 'bank', now()),
('h7', 'math', 3, 'Geometry and Trigonometry', 'Right triangles and trigonometry', null, null, 'In right triangle ABC, angle C is the right angle. If cos A = 0.6, what is the value of sin B?', '["0.4","0.6","0.75","0.8"]'::jsonb, 1, null, 'A and B are complementary, and the sine of an angle equals the cosine of its complement. So sin B = cos A = 0.6.', 'published', 'bank', now()),
('h8', 'math', 3, 'Advanced Math', 'Nonlinear functions', null, null, 'The function g is defined by g(x) = x^{2} − 10x + 31. What is the minimum value of g(x)?', null, null, '["6"]'::jsonb, 'Complete the square: g(x) = (x − 5)² + 6. The squared term is at least 0, so the minimum is 6.', 'published', 'bank', now()),
('h9', 'math', 3, 'Advanced Math', 'Equivalent expressions', null, null, '(ax − 2)(2x + b) = 6x^{2} + 5x − 6
The equation above is true for all values of x, where a and b are constants. What is the value of a + b?', null, null, '["6"]'::jsonb, 'Expanding gives 2ax² + (ab − 4)x − 2b. So 2a = 6 (a = 3) and −2b = −6 (b = 3). Check: ab − 4 = 5. a + b = 6.', 'published', 'bank', now()),
('h10', 'math', 3, 'Geometry and Trigonometry', 'Circles', null, null, 'A circle has a radius of 6. What is the length of an arc of the circle intercepted by a central angle of 120°?', '["2π","4π","6π","12π"]'::jsonb, 1, null, 'The arc is 120/360 = 1/3 of the circumference 12π, which is 4π.', 'published', 'bank', now()),
('h11', 'math', 3, 'Problem-Solving and Data Analysis', 'Two-variable data', null, null, 'The equation F = 1.8C + 32 converts a temperature C in degrees Celsius to a temperature F in degrees Fahrenheit. What is the best interpretation of 1.8 in this context?', '["Each increase of 1 degree Celsius corresponds to an increase of 1.8 degrees Fahrenheit.","Each increase of 1 degree Fahrenheit corresponds to an increase of 1.8 degrees Celsius.","The Fahrenheit temperature is 1.8 when the Celsius temperature is 0.","The Celsius temperature is 1.8 times the Fahrenheit temperature."]'::jsonb, 0, null, '1.8 is the slope: the change in F for each 1-unit change in C.', 'published', 'bank', now()),
('h12', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'What is the sum of the solutions to 2x^{2} − 7x + 3 = 0?', null, null, '["3.5","7/2"]'::jsonb, 'Factor: (2x − 1)(x − 3) = 0, so x = 1/2 or x = 3. Their sum is 7/2. (For ax² + bx + c = 0 the sum is always −b/a.)', 'published', 'bank', now()),
('h13', 'math', 3, 'Algebra', 'Linear equations in one variable', null, null, 'What is the product of all solutions to |2x − 5| = 9?', '["−14","−5","5","14"]'::jsonb, 0, null, '2x − 5 = 9 gives x = 7. 2x − 5 = −9 gives x = −2. The product is −14.', 'published', 'bank', now()),
('h14', 'math', 3, 'Advanced Math', 'Nonlinear equations', null, null, 'If 2^{x + 3} = 32^{x − 1}, what is the value of x?', null, null, '["2"]'::jsonb, '32 = 2⁵, so 2^(x+3) = 2^(5x−5). Then x + 3 = 5x − 5, so 8 = 4x and x = 2.', 'published', 'bank', now()),
('h15', 'math', 3, 'Problem-Solving and Data Analysis', 'Probability and conditional probability', null, null, 'At a school, 70 students take Spanish and 50 students do not. Of the Spanish students, 28 are in the band. Of the other students, 22 are in the band. If a band member is chosen at random, what is the probability that the student takes Spanish?', '["0.233","0.40","0.44","0.56"]'::jsonb, 3, null, 'There are 28 + 22 = 50 band members, and 28 take Spanish. 28 ÷ 50 = 0.56.', 'published', 'bank', now()),
('r1', 'rw', 1, 'Craft and Structure', 'Words in Context', 'The new library’s reading room was designed to be ______: its tall windows let in natural light from early morning until late afternoon.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["dim","bright","cramped","silent"]'::jsonb, 1, null, 'The colon introduces support for the blank. Windows letting in light all day describe a bright room.', 'published', 'bank', now()),
('r2', 'rw', 1, 'Expression of Ideas', 'Transitions', 'Honeybees share the location of food through a movement called the waggle dance. ______ the angle of the dance tells other bees which direction to fly.', null, 'Which choice completes the text with the most logical transition?', '["Specifically,","However,","Instead,","In contrast,"]'::jsonb, 0, null, 'The second sentence gives a specific detail about how the dance works, so “Specifically” fits. The others signal contrast.', 'published', 'bank', now()),
('r3', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'Maya packed everything she needed for the camping ______ a tent, a sleeping bag, and a flashlight.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["trip:","trip, and","trip;","trip."]'::jsonb, 0, null, 'A colon can introduce a list after a complete sentence. A semicolon or period would leave the list as a fragment.', 'published', 'bank', now()),
('r4', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The collection of old maps in the museum’s basement ______ more than 300 years old.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["is","are","were","have been"]'::jsonb, 0, null, 'The subject is “collection,” which is singular, so the verb is “is.” “Maps” is inside a prepositional phrase.', 'published', 'bank', now()),
('r5', 'rw', 1, 'Information and Ideas', 'Central Ideas and Details', 'Rooftop gardens are becoming common in large cities. Besides providing fresh vegetables, the gardens absorb rainwater that would otherwise flood streets, and their plants help keep buildings cooler during hot summers.', null, 'Which choice best states the main idea of the text?', '["Rooftop gardens offer cities several benefits beyond growing food.","Rooftop gardens are difficult and expensive to maintain.","Most of the food eaten in large cities is grown on rooftops.","Rooftop gardens make buildings warmer in the summer."]'::jsonb, 0, null, 'The text lists food plus two other benefits: less flooding and cooler buildings.', 'published', 'bank', now()),
('r6', 'rw', 1, 'Craft and Structure', 'Text Structure and Purpose', 'Many people assume that deserts are nearly lifeless. Yet the Sonoran Desert is home to more than 2,000 plant species, from the towering saguaro cactus to tiny wildflowers that bloom only after spring rains.', null, 'Which choice best states the main purpose of the text?', '["To challenge a common assumption by describing the variety of plant life in one desert","To explain how the saguaro cactus stores water","To argue that deserts need more protection","To describe the weather of the Sonoran Desert in spring"]'::jsonb, 0, null, 'The text states an assumption (“lifeless”) and then gives evidence against it.', 'published', 'bank', now()),
('r7', 'rw', 1, 'Information and Ideas', 'Inferences', 'Ms. Ortiz noticed that students who reviewed their notes for ten minutes each evening scored higher on weekly quizzes than students who studied only the night before. She concluded that ______', null, 'Which choice most logically completes the text?', '["short, regular review may help students remember material better than last-minute studying.","students should never study the night before a quiz.","the weekly quizzes were too difficult for most students.","taking notes in class is unnecessary."]'::jsonb, 0, null, 'Her observation compares regular review with last-minute studying. The other choices claim more than the evidence shows.', 'published', 'bank', now()),
('r8', 'rw', 1, 'Craft and Structure', 'Words in Context', 'Although the first draft of the essay was ______, the final version was concise and focused.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["brief","wordy","accurate","organized"]'::jsonb, 1, null, '“Although” signals a contrast with “concise.” The opposite of concise is wordy.', 'published', 'bank', now()),
('r9', 'rw', 1, 'Expression of Ideas', 'Transitions', 'The team’s first robot prototype was too heavy to climb stairs. ______ the engineers replaced its steel frame with lightweight aluminum.', null, 'Which choice completes the text with the most logical transition?', '["As a result,","Similarly,","For example,","Meanwhile,"]'::jsonb, 0, null, 'Replacing the frame is a response to the robot being too heavy: cause and effect.', 'published', 'bank', now()),
('r10', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'The two scientists published ______ findings in a respected journal.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["its","their","his","her"]'::jsonb, 1, null, 'The antecedent “two scientists” is plural, so the pronoun is “their.”', 'published', 'bank', now()),
('r11', 'rw', 1, 'Standard English Conventions', 'Form, Structure, and Sense', 'Last summer, my grandmother ______ me how to bake bread from scratch.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["teaches","will teach","taught","is teaching"]'::jsonb, 2, null, '“Last summer” places the action in the past, so the past tense “taught” is correct.', 'published', 'bank', now()),
('r12', 'rw', 1, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• The Great Wall of China is a series of fortifications.
• Construction of early walls began in the 7th century BCE.
• The best-known sections were built during the Ming dynasty (1368–1644).
Goal: emphasize when the best-known sections of the wall were built.', null, 'The student wants to accomplish the goal below. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The best-known sections of the Great Wall of China were built during the Ming dynasty, between 1368 and 1644.","The Great Wall of China is a series of fortifications.","Construction of early walls began in the 7th century BCE.","The Great Wall of China is famous around the world."]'::jsonb, 0, null, 'Only this choice names when the best-known sections were built.', 'published', 'bank', now()),
('r13', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A student claims that octopuses are capable of solving problems.', null, 'Which finding, if true, would most directly support the student’s claim?', '["In a laboratory study, octopuses learned to unscrew jar lids to reach food inside.","Octopuses have eight arms lined with suction cups.","Octopuses are found in every ocean on Earth.","Some octopuses can change color to match their surroundings."]'::jsonb, 0, null, 'Opening a jar to reach food is an example of solving a problem. The others describe the animal but not its problem solving.', 'published', 'bank', now()),
('r14', 'rw', 1, 'Standard English Conventions', 'Boundaries', 'The museum opened in ______ it has welcomed more than five million visitors since then.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1998,","1998;","1998","1998, which"]'::jsonb, 1, null, 'Both parts are complete sentences. A semicolon can join them; a comma alone creates a comma splice.', 'published', 'bank', now()),
('r15', 'rw', 1, 'Information and Ideas', 'Command of Evidence', 'A student surveyed classmates about how many hours of screen time they have on an average day. The student claims that screen time increases with grade level.', '{"h":["Grade","Average daily screen time (hours)"],"r":[["6th","3.1"],["7th","3.6"],["8th","4.2"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the student’s claim?', '["Average daily screen time rose from 3.1 hours in 6th grade to 4.2 hours in 8th grade.","Eighth graders use their phones more than their computers.","Sixth graders spend about 3.1 hours on homework each day.","Seventh graders spend 3.6 hours outdoors on an average day."]'::jsonb, 0, null, 'Only choice A uses the table accurately and shows an increase across grades.', 'published', 'bank', now()),
('s1', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The chemist’s explanation was so ______ that even students with no background in science could follow it.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["lucid","obscure","tentative","lengthy"]'::jsonb, 0, null, 'Something easy to follow is lucid (clear). Obscure means hard to understand.', 'published', 'bank', now()),
('s2', 'rw', 2, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Some historians argue that the printing press was the single most important cause of the spread of literacy in Europe, since it made books far cheaper to produce.

Text 2
Literacy rates in many European regions rose only slowly for more than a century after the printing press was invented. They climbed sharply only once public schooling became widespread.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the historians in Text 1?', '["By suggesting that other factors, such as schooling, also played a major role in spreading literacy","By agreeing that the printing press alone explains the rise in literacy","By arguing that the printing press made books more expensive","By claiming that literacy rates fell after the printing press was invented"]'::jsonb, 0, null, 'Text 2 points to schooling as the moment literacy rose sharply, which complicates the “single most important cause” claim.', 'published', 'bank', now()),
('s3', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Coral reefs cover less than 1 percent of the ocean floor. ______ they support roughly a quarter of all known marine species.', null, 'Which choice completes the text with the most logical transition?', '["Nevertheless,","Therefore,","Similarly,","For instance,"]'::jsonb, 0, null, 'A tiny area supporting a huge share of species is a surprising contrast, so “Nevertheless” fits.', 'published', 'bank', now()),
('s4', 'rw', 2, 'Standard English Conventions', 'Boundaries', 'Marie ______ was the first person to win Nobel Prizes in two different sciences.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Curie, who studied radioactivity,","Curie who studied radioactivity,","Curie, who studied radioactivity","Curie; who studied radioactivity,"]'::jsonb, 0, null, 'The clause “who studied radioactivity” adds extra information, so it needs a comma on both sides.', 'published', 'bank', now()),
('s5', 'rw', 2, 'Information and Ideas', 'Inferences', 'In a study of city parks, researchers found that parks with many trees had slightly fewer visitors in winter but far more visitors in summer than parks with few trees. The researchers suggested that ______', null, 'Which choice most logically completes the text?', '["the shade provided by trees may make parks more attractive in hot weather.","trees make winter weather colder in cities.","most people prefer parks without any trees.","parks with few trees are usually closed in the summer."]'::jsonb, 0, null, 'The big difference appears in summer, when shade matters most. The other choices are not supported.', 'published', 'bank', now()),
('s6', 'rw', 2, 'Craft and Structure', 'Text Structure and Purpose', 'The poet Lena Morales was known for revising her work slowly. She once kept the draft of a single short poem pinned above her desk for six years, changing a word or two at a time until she felt it was finished.', null, 'Which choice best describes the function of the second sentence in the text as a whole?', '["It gives a specific example that illustrates the claim in the first sentence.","It presents a view that contradicts the first sentence.","It introduces a topic unrelated to the first sentence.","It summarizes an argument made by Morales’s critics."]'::jsonb, 0, null, 'The first sentence makes a general claim (slow revision). The second gives a concrete case of it.', 'published', 'bank', now()),
('s7', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'Running to catch the bus, ______', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Jamal’s backpack fell open.","Jamal felt his backpack fall open.","the backpack of Jamal fell open.","it was Jamal’s backpack that fell open."]'::jsonb, 1, null, 'The opening phrase describes someone running, so the subject right after the comma must be Jamal, not the backpack.', 'published', 'bank', now()),
('s8', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'In the novel The River Keeper, the narrator describes her older brother, Tomás, as extremely stubborn.', null, 'Which quotation from the novel most effectively illustrates this description?', '["“Once Tomás decided something, no argument from anyone could move him an inch.”","“Tomás liked to walk along the river in the early morning.”","“Tomás was taller than anyone else in our family.”","“Tomás had a laugh that filled the whole kitchen.”"]'::jsonb, 0, null, 'Refusing to change his mind no matter what is what stubborn means.', 'published', 'bank', now()),
('s9', 'rw', 2, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Tardigrades are microscopic animals about 0.5 millimeters long.
• They can survive temperatures close to absolute zero.
• In 2007, tardigrades survived exposure to outer space during a satellite mission.
Goal: emphasize tardigrades’ ability to survive extreme conditions.', null, 'The student wants to accomplish the goal below. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Tardigrades can survive extreme conditions, including temperatures close to absolute zero and exposure to outer space.","Tardigrades are microscopic animals about 0.5 millimeters long.","In 2007, a satellite mission was launched into outer space.","Tardigrades are animals that scientists have studied for many years."]'::jsonb, 0, null, 'Only choice A combines the notes about extreme cold and space to stress survival.', 'published', 'bank', now()),
('s10', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The results of the experiment, which took three years to complete, ______ that the new fertilizer increased crop yields.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["suggest","suggests","has suggested","was suggesting"]'::jsonb, 0, null, 'The subject is “results” (plural), so the verb is “suggest.” Skip past the clause between commas to find the subject.', 'published', 'bank', now()),
('s11', 'rw', 2, 'Craft and Structure', 'Words in Context', 'The committee’s ruling was ______: once announced, it could not be changed or appealed.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["irrevocable","provisional","ambiguous","unanimous"]'::jsonb, 0, null, 'A decision that cannot be changed or appealed is irrevocable. Provisional means temporary.', 'published', 'bank', now()),
('s12', 'rw', 2, 'Information and Ideas', 'Central Ideas and Details', 'Cities are often several degrees warmer than the countryside around them, a pattern known as the urban heat island effect. Dark surfaces such as asphalt absorb sunlight during the day and release heat at night, while a lack of plants reduces cooling. Some cities have begun painting roofs white and planting street trees to fight these effects.', null, 'Which choice best states the main idea of the text?', '["Urban heat islands result from features of city surfaces, and some cities are working to reduce them.","Asphalt is the most common building material in cities.","Rural areas are always cooler than cities at night.","Painting roofs white is the only way to cool a city."]'::jsonb, 0, null, 'The text explains causes of the effect and then responses to it. The other choices are details or overstatements.', 'published', 'bank', now()),
('s13', 'rw', 2, 'Expression of Ideas', 'Transitions', 'Many early critics dismissed the painter’s work as too simple. Today, ______ her paintings hang in major museums around the world.', null, 'Which choice completes the text with the most logical transition?', '["however,","for example,","likewise,","in addition,"]'::jsonb, 0, null, 'Dismissal then, museum display now: a contrast, so “however.”', 'published', 'bank', now()),
('s14', 'rw', 2, 'Standard English Conventions', 'Form, Structure, and Sense', 'The three ______ uniforms arrived just before the championship tournament.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["teams’","team’s","teams","teams’s"]'::jsonb, 0, null, 'The uniforms belong to three teams, so use the plural possessive “teams’.”', 'published', 'bank', now()),
('s15', 'rw', 2, 'Information and Ideas', 'Command of Evidence', 'Researchers studying energy use note that solar power has grown rapidly in Country X, ______', '{"h":["Year","Share of Country X’s electricity from solar"],"r":[["2015","2%"],["2018","5%"],["2021","9%"]]}'::jsonb, 'Which choice most effectively uses data from the table to complete the text?', '["rising from 2% of the country’s electricity in 2015 to 9% in 2021.","reaching 2% of the country’s electricity in 2021.","falling from 9% in 2015 to 2% in 2021.","remaining at 5% between 2015 and 2021."]'::jsonb, 0, null, 'Only choice A matches the table and shows rapid growth.', 'published', 'bank', now()),
('t1', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Rather than offering a sweeping theory, the economist’s paper was deliberately ______, addressing only the narrow question of how minimum-wage changes affected small restaurants in a single state.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["circumscribed","grandiose","derivative","polemical"]'::jsonb, 0, null, 'Circumscribed means limited in scope, which matches “only the narrow question.”', 'published', 'bank', now()),
('t2', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Critics found the novelist’s latest book ______: its plot copied the structure of her earlier work so closely that readers could predict every turn.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["derivative","innovative","opaque","whimsical"]'::jsonb, 0, null, 'Derivative means borrowed from earlier work, which fits a copied plot.', 'published', 'bank', now()),
('t3', 'rw', 3, 'Craft and Structure', 'Cross-Text Connections', 'Text 1
Researchers studying crows argue that the birds plan ahead. In experiments, crows chose tools that would be useful for a task they would face only later.

Text 2
In many of these experiments, the crows had extensive earlier training with the same tools. Their choices may therefore reflect learned associations between particular tools and food rather than genuine planning.', null, 'Based on the texts, how would the author of Text 2 most likely respond to the researchers in Text 1?', '["By arguing that the experimental results could be explained without assuming that crows plan for the future","By claiming that crows are unable to use tools","By agreeing that the experiments prove crows plan ahead","By stating that the experiments described in Text 1 never took place"]'::jsonb, 0, null, 'Text 2 offers an alternative explanation (training) for the same results.', 'published', 'bank', now()),
('t4', 'rw', 3, 'Craft and Structure', 'Text Structure and Purpose', 'Ecologists long assumed that the deep ocean floor was a stable environment where conditions rarely changed. Recent long-term monitoring, however, has revealed that the amount of organic material drifting down from the surface varies dramatically from season to season and from year to year. These swings, in turn, appear to drive sudden changes in the populations of deep-sea animals.', null, 'Which choice best describes the overall structure of the text?', '["It describes a long-held assumption and then presents findings that complicate it.","It presents two competing theories and declines to choose between them.","It describes an experiment and then explains why its methods were flawed.","It lists several deep-sea animals and describes their feeding habits."]'::jsonb, 0, null, 'First the old assumption (stable), then the “however” findings (big swings).', 'published', 'bank', now()),
('t5', 'rw', 3, 'Information and Ideas', 'Inferences', 'Linguists have observed that languages spoken by large populations tend to have simpler systems of word endings than languages spoken by small, isolated communities. One explanation is that when many adults learn a language as a second language, they tend to drop complex endings that are hard to master. If this explanation is correct, then a language ______', null, 'Which choice most logically completes the text?', '["that has historically been learned by many adult nonnative speakers would be expected to have relatively simple word endings.","spoken by a small community must be easy for adults to learn.","with simple word endings must be spoken by a large population.","spoken by a large population cannot have any word endings at all."]'::jsonb, 0, null, 'The explanation links adult learners to simpler endings. The other choices reverse the logic or overstate it with “must” and “cannot.”', 'published', 'bank', now()),
('t6', 'rw', 3, 'Information and Ideas', 'Command of Evidence', 'A student compared two fertilizers in a six-week greenhouse trial. The student claims that fertilizer B may be the better choice for drought-prone regions, even though fertilizer A produced taller plants.', '{"h":["Treatment","Average height (cm)","Water used per plant (L)"],"r":[["No fertilizer","12","2.0"],["Fertilizer A","18","3.1"],["Fertilizer B","15","2.2"]]}'::jsonb, 'Which choice most effectively uses data from the table to support the student’s claim?', '["Plants given fertilizer B grew to 15 cm while using 2.2 liters of water, compared with 18 cm and 3.1 liters for fertilizer A.","Plants given fertilizer A grew to an average height of 18 cm.","Plants given no fertilizer used 2.0 liters of water per plant.","Plants given fertilizer B grew taller than plants given no fertilizer."]'::jsonb, 0, null, 'The claim is about drought, so the evidence must show B uses much less water while still growing well. Only A makes that comparison.', 'published', 'bank', now()),
('t7', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The expedition’s final discovery—a feather preserved in ______ changed how scientists understood the coloring of some dinosaurs.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["amber—","amber,","amber","amber;"]'::jsonb, 0, null, 'The interruption opened with a dash, so it must close with a dash.', 'published', 'bank', now()),
('t8', 'rw', 3, 'Standard English Conventions', 'Boundaries', 'The festival featured performers from three cities: Lagos, Nigeria; Recife, ______ and Osaka, Japan.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Brazil;","Brazil,","Brazil","Brazil:"]'::jsonb, 0, null, 'When list items already contain commas, semicolons separate the items. Keep the pattern used after “Nigeria.”', 'published', 'bank', now()),
('t9', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'By the time the rescue team reached the summit, the storm ______ for nearly six hours.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["had been raging","rages","will have raged","has raged"]'::jsonb, 0, null, 'The storm’s raging happened before a past event (reaching the summit), so use the past perfect progressive “had been raging.”', 'published', 'bank', now()),
('t10', 'rw', 3, 'Expression of Ideas', 'Transitions', 'The city council expected the new bike lanes to reduce traffic congestion. A study conducted a year later found no significant change in commute times. ______ the lanes were associated with a 30 percent decline in cyclist injuries, a benefit planners had not emphasized.', null, 'Which choice completes the text with the most logical transition?', '["Still,","Consequently,","In other words,","For instance,"]'::jsonb, 0, null, 'Despite failing the original goal, the lanes had another benefit. “Still” introduces a point that holds in spite of what came before.', 'published', 'bank', now()),
('t11', 'rw', 3, 'Expression of Ideas', 'Rhetorical Synthesis', 'While researching a topic, a student has taken the following notes:
• Lise Meitner was an Austrian-Swedish physicist.
• In 1938–39, she and Otto Frisch provided the theoretical explanation of nuclear fission.
• Otto Hahn received the 1944 Nobel Prize in Chemistry for the discovery of fission.
• Meitner was not included in the prize.
Goal: highlight a contrast between Meitner’s contribution and the recognition she received.', null, 'The student wants to accomplish the goal below. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Although Lise Meitner helped explain nuclear fission, she was not included when Otto Hahn received the 1944 Nobel Prize in Chemistry for its discovery.","Lise Meitner was an Austrian-Swedish physicist who worked with Otto Frisch.","Otto Hahn received the 1944 Nobel Prize in Chemistry for the discovery of fission.","In 1938–39, Meitner and Frisch provided the theoretical explanation of nuclear fission."]'::jsonb, 0, null, '“Although” sets up the contrast between her contribution and her exclusion from the prize.', 'published', 'bank', now()),
('t12', 'rw', 3, 'Information and Ideas', 'Central Ideas and Details', 'Grandfather’s workshop smelled of cedar and machine oil. Every tool hung inside its painted outline on the pegboard, and when I borrowed a chisel, I learned quickly to return it to its exact shape on the wall. “A tool out of place is a tool lost,” he would say, though I suspected he could have found any of them blindfolded.', null, 'Based on the text, how does the narrator most likely view Grandfather’s rule about tools?', '["As a reflection of his orderly habits more than a real necessity","As evidence that he often lost his tools","As an unfair rule that the narrator refused to follow","As a sign that he was becoming forgetful"]'::jsonb, 0, null, 'The narrator follows the rule but suspects Grandfather could find any tool blindfolded, so the rule reflects habit rather than need.', 'published', 'bank', now()),
('t13', 'rw', 3, 'Information and Ideas', 'Inferences', 'Archaeologists found that pottery from a coastal settlement contained residue of fish oils, while pottery from an inland settlement 200 kilometers away contained residue of both fish oils and grains. Because the inland settlement had no access to the sea, the researchers concluded that ______', null, 'Which choice most logically completes the text?', '["the inland community likely obtained fish products through trade or travel.","the coastal community grew large amounts of grain.","fish oils do not leave lasting residue on pottery.","the inland settlement was founded after the coastal one."]'::jsonb, 0, null, 'An inland group without sea access that had fish oils must have gotten fish from elsewhere.', 'published', 'bank', now()),
('t14', 'rw', 3, 'Standard English Conventions', 'Form, Structure, and Sense', 'Neither the coach nor the players ______ aware that the game had been moved to Saturday.', null, 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["were","was","is","has been"]'::jsonb, 0, null, 'With “neither…nor,” the verb agrees with the nearer subject, “players,” which is plural: “were.”', 'published', 'bank', now()),
('t15', 'rw', 3, 'Craft and Structure', 'Words in Context', 'Far from being ______, the historian’s account acknowledges the limitations of its sources at nearly every turn.', null, 'Which choice completes the text with the most logical and precise word or phrase?', '["dogmatic","meticulous","candid","modest"]'::jsonb, 0, null, '“Far from” signals the opposite of acknowledging limits. Dogmatic means asserting views as unquestionably true.', 'published', 'bank', now())
on conflict (id) do nothing;
